<script setup>
// Reference SHA-256: 91D03978BB5A413EBF79A2CDC25E00EABBF79499F65B672A267BFAB19596FB39
import { computed, reactive, ref } from 'vue';
import TypeLineIcon from '../components/TypeLineIcon.vue';

const props=defineProps({integrationData:{type:Object,default:null},integrationState:{type:String,default:'mock'}});
const types=reactive([
  {icon:'visual',name:'可视化',code:'VISUAL',description:'大屏与驾驶舱可视化应用',sort:1,enabled:true},{icon:'report',name:'报表',code:'REPORT',description:'报表设计、分析与导出应用',sort:2,enabled:true},{icon:'rpa',name:'RPA',code:'RPA',description:'流程自动化与机器人应用',sort:3,enabled:true},{icon:'dataset',name:'数据集',code:'DATASET',description:'标准数据资源集合与管理',sort:4,enabled:true},{icon:'metric',name:'指标',code:'METRIC',description:'指标定义、口径与分析服务',sort:5,enabled:true},{icon:'ai',name:'AI',code:'AI_AGENT',description:'智能交互、分析与协同应用',sort:6,enabled:true},{icon:'work',name:'海能work应用',code:'HAINENG_WORK',description:'海能work协同办公应用',sort:7,enabled:true},{icon:'ead',name:'EAD',code:'EAD',description:'企业架构设计与治理应用',sort:8,enabled:true},{icon:'tools',name:'其他工具',code:'OTHER_TOOL',description:'其他通用数字化工具',sort:9,enabled:true}
]);
const domains=reactive([
  {icon:'visual',name:'生产运营',types:'可视化 / 报表 / 数据集',sort:1,enabled:true},{icon:'metric',name:'市场营销',types:'报表 / 指标',sort:2,enabled:true},{icon:'dataset',name:'物资采购',types:'数据集 / RPA / AI',sort:3,enabled:true},{icon:'report',name:'财务管理',types:'报表 / 指标 / RPA',sort:4,enabled:true},{icon:'work',name:'人力资源',types:'海能work应用 / 报表',sort:5,enabled:true},{icon:'ead',name:'安全环保',types:'可视化 / 数据集 / EAD',sort:6,enabled:true},{icon:'tools',name:'工程建设',types:'数据集 / 其他工具',sort:7,enabled:true},{icon:'metric',name:'成本控制',types:'指标 / 报表',sort:8,enabled:true},{icon:'apps',name:'综合管理',types:'海能work应用 / AI',sort:9,enabled:true}
]);
const logRows=[['2026-09-01 09:45:17','/api/auth/login','登录','IAM 单点登录策略校验，记录号 FX-817-0','待处理'],['2026-09-01 09:41:17','/api/data/sync','同步','采购主数据增量同步完成，记录号 FX-817-1','待处理'],['2026-09-01 09:37:17','/api/report/export','导出','经营月报导出任务完成，记录号 FX-817-2','已处理'],['2026-09-01 09:33:17','/api/file/upload','上传','应用上架资料完成安全扫描，记录号 FX-817-3','已处理'],['2026-09-01 09:29:17','/api/user/info','查询','用户组织权限范围校验完成，记录号 FX-817-4','已处理']];
const announcement=ref('');
const topicDomainDialog=ref(false);
const topicDomain=reactive({name:'',types:'',icon:'apps'});
const remoteMode=computed(()=>props.integrationState!=='mock');
const remoteState=computed(()=>props.integrationState);
const remoteConnections=computed(()=>Array.isArray(props.integrationData?.['INT-001']?.items)?props.integrationData['INT-001'].items:[]);
const remoteAuditRows=computed(()=>[
  ...(Array.isArray(props.integrationData?.['ADM-003']?.items)?props.integrationData['ADM-003'].items.map(item=>({time:item.occurredAt||'',target:item.path||item.resourceName||item.resourceId||'—',type:item.actionName||item.actionCode||'审计',detail:item.resultMessage||item.moduleCode||'—',status:item.resultCode||'—'})):[]),
  ...(Array.isArray(props.integrationData?.['ADM-004']?.items)?props.integrationData['ADM-004'].items.map(item=>({time:item.startedAt||'',target:item.endpointMasked||item.integrationName||item.integrationCode||'—',type:item.operationCode||'集成',detail:item.errorMessageMasked||item.direction||'—',status:item.status||'—'})):[])
]);
const remoteExecutions=computed(()=>Array.isArray(props.integrationData?.['INT-004']?.items)?props.integrationData['INT-004'].items:[]);
const archiveDetail=computed(()=>props.integrationData?.['ARC-002']??null);
const sensitiveKey=/token|secret|cookie|authorization|credential|password/i;
function safeValue(value){return typeof value==='string'||typeof value==='number'||typeof value==='boolean'?String(value):'';}
function safeEntries(operationId){
  const source=props.integrationData?.[operationId];
  if(!source||typeof source!=='object')return [];
  return Object.entries(source).filter(([key,value])=>!sensitiveKey.test(key)&&safeValue(value)!=='').slice(0,12).map(([key,value])=>({id:`${operationId}-${key}`,key,value:safeValue(value)}));
}
const authoritySections=computed(()=>[
  {id:'ADM-006',title:'治理策略读取',rows:safeEntries('ADM-006')},
  {id:'ADM-007',title:'权限判定读取',rows:safeEntries('ADM-007')},
  {id:'INT-003',title:'集成配置校验',rows:safeEntries('INT-003')},
  {id:'INT-005',title:'集成差异校验',rows:safeEntries('INT-005')}
]);
const currentConnections=computed(()=>remoteMode.value?remoteConnections.value:[]);
const currentLogRows=computed(()=>remoteMode.value?remoteAuditRows.value:logRows.map(([time,target,type,detail,status])=>({time,target,type,detail,status})));
const pageState=computed(()=>{
  if(!remoteMode.value)return 'normal';
  if(remoteState.value==='error'||remoteState.value==='timeout'||remoteState.value==='rate-limited'||remoteState.value==='schema-drift'||remoteState.value==='security-error')return 'error';
  if(remoteState.value==='authentication-required'||remoteState.value==='permission-denied')return 'permission-denied';
  if(remoteState.value==='disabled')return 'disabled';
  if(remoteState.value==='empty')return 'empty';
  if(remoteState.value==='loading')return 'loading';
  return 'normal';
});
function action(label,name){announcement.value=remoteMode.value?`${name}：正式配置写入合同尚未提供，本次未发送飞书请求。`:`${name}：${label}操作已记录为当前浏览器会话`;}
function openTopicDomainDialog(){topicDomainDialog.value=true;announcement.value=remoteMode.value?'正式配置写入合同尚未提供；可查看填写项，但提交不会发送飞书请求。':'';}
function closeTopicDomainDialog(){topicDomainDialog.value=false;topicDomain.name='';topicDomain.types='';topicDomain.icon='apps';}
function saveTopicDomain(){
  if(!topicDomain.name.trim()){announcement.value='请填写主题域名称。';return;}
  if(remoteMode.value){announcement.value='正式配置写入合同尚未提供，本次未发送飞书请求。';return;}
  domains.push({icon:topicDomain.icon,name:topicDomain.name.trim(),types:topicDomain.types.trim()||'未关联应用类型',sort:domains.length+1,enabled:true});
  announcement.value=`主题域“${topicDomain.name.trim()}”已加入当前浏览器会话，未写入飞书。`;
  closeTopicDomainDialog();
}
</script>

<template>
  <article class="backend-page" aria-labelledby="backend-title" :data-state="pageState">
    <p class="sr-only" aria-live="polite">{{ announcement }}</p>
    <nav>运营管理　/　后台管理</nav>
    <header><h1 id="backend-title">后台管理</h1><p>管理应用类型、主题域与操作日志，保障平台配置一致、可追溯。</p></header>
    <p v-if="announcement" class="admin-feedback" role="status">{{ announcement }}</p>
    <section v-if="pageState==='loading'" class="admin-state-surface" role="status">正在加载后台管理的受控只读数据…</section>
    <section v-else-if="pageState==='permission-denied'" class="admin-state-surface" role="alert">需要完成飞书授权或获得后台只读权限后才能查看数据。</section>
    <section v-else-if="pageState==='error'" class="admin-state-surface" role="alert">后台管理数据暂不可用。请检查登录状态或稍后重试。</section>
    <section v-else-if="pageState==='disabled'" class="admin-state-surface" role="status">后台管理真实读取尚未启用；正式配置写入合同尚未提供。</section>
    <section v-else-if="pageState==='empty'" class="admin-state-surface" role="status">当前没有可展示的真实后台日志或集成健康记录。</section>
    <template v-else>
      <div v-if="remoteMode" class="config-grid">
        <section><div class="section-heading"><div><h2>受控集成连接</h2><p>仅显示已授权的连接摘要和健康状态。</p></div></div><div class="table-scroll"><table><thead><tr><th>连接编码</th><th>业务域</th><th>读取状态</th><th>最后校验</th><th>健康状态</th></tr></thead><tbody><tr v-for="item in currentConnections" :key="item.connectionCode"><td><strong>{{ item.connectionCode }}</strong></td><td>{{ item.domainCode||'—' }}</td><td>{{ item.readEnabled?'已启用':'未启用' }}</td><td>{{ item.lastVerifiedAt||'—' }}</td><td>{{ item.lastVerifiedStatus||'—' }}</td></tr></tbody></table></div></section>
        <section><div class="section-heading"><div><h2>正式配置读取未配置</h2><p>ADM-001/ADM-002 尚未验证，不能展示或推断应用类型与主题域配置。</p></div><button type="button" @click="openTopicDomainDialog">查看写入限制</button></div><p class="blocked-copy">新增、修改、删除、排序及归档恢复均需正式权限与写入合同。</p><button type="button" @click="openTopicDomainDialog">新增主题域</button></section>
      </div>
      <div v-else class="config-grid">
        <section><div class="section-heading"><div><h2>应用类型配置</h2><p>类型与前台分类共用同一套线稿图标和排序规则。</p></div></div><div class="table-scroll"><table><thead><tr><th>应用类型名称</th><th>类型说明 / 描述</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in types" :key="item.code"><td><span class="table-icon"><TypeLineIcon :name="item.icon" :size="20" /></span><strong>{{ item.name }}</strong></td><td><b>{{ item.code }}</b><small>{{ item.description }}</small></td><td><input v-model.number="item.sort" class="sort-input" type="number" min="1" :max="types.length" inputmode="numeric" :aria-label="`${item.name}排序`" /></td><td><label class="switch"><input v-model="item.enabled" type="checkbox" />{{ item.enabled?'启用':'停用' }}</label></td><td><button type="button" @click="action('编辑',item.name)">编辑</button><button type="button" @click="action('删除',item.name)">删除</button></td></tr></tbody></table></div></section>
        <section><div class="section-heading"><div><h2>主题域配置</h2><p>图标按业务含义关联，避免使用无关随机图标。</p></div><button type="button" @click="action('新增','主题域')">新增主题域</button></div><div class="table-scroll"><table><thead><tr><th>图标</th><th>主题域名称</th><th>所属应用 / 类型</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in domains" :key="item.name"><td><span class="table-icon"><TypeLineIcon :name="item.icon" :size="20" /></span></td><td><strong>{{ item.name }}</strong></td><td>{{ item.types }}</td><td><input v-model.number="item.sort" class="sort-input" type="number" min="1" :max="domains.length" inputmode="numeric" :aria-label="`${item.name}排序`" /></td><td><label class="switch"><input v-model="item.enabled" type="checkbox" />{{ item.enabled?'启用':'停用' }}</label></td><td><button type="button" @click="action('编辑',item.name)">编辑</button><button type="button" @click="action('删除',item.name)">删除</button></td></tr></tbody></table></div></section>
      </div>
      <section v-if="remoteMode" class="authority-panel"><div class="section-heading"><div><h2>权威治理与集成校验</h2><p>仅投影上游实际返回的安全标量字段，不补造配置。</p></div></div><div class="authority-grid"><section v-for="section in authoritySections" :key="section.id"><h3>{{ section.title }}</h3><dl v-if="section.rows.length"><div v-for="row in section.rows" :key="row.id"><dt>{{ row.key }}</dt><dd>{{ row.value }}</dd></div></dl><p v-else class="section-empty">该项未返回可展示数据。</p></section></div></section>
      <section v-if="remoteMode" class="task-panel"><div class="section-heading"><div><h2>后台任务与归档摘要</h2><p>任务执行和归档详情仅展示已授权的安全投影。</p></div></div><div v-if="remoteExecutions.length||archiveDetail" class="table-scroll"><table><thead><tr><th>执行标识</th><th>状态</th><th>进度</th><th>开始时间</th><th>完成时间</th></tr></thead><tbody><tr v-for="item in remoteExecutions" :key="item.executionId||item.taskExecutionId"><td>{{ item.executionId||item.taskExecutionId||'—' }}</td><td>{{ item.status||'—' }}</td><td>{{ item.progress??'—' }}</td><td>{{ item.startedAt||'—' }}</td><td>{{ item.finishedAt||'—' }}</td></tr><tr v-if="archiveDetail"><td>{{ archiveDetail.archiveTaskId }}</td><td>{{ archiveDetail.status||'—' }}</td><td>{{ archiveDetail.stage||'—' }}</td><td>{{ archiveDetail.verifiedAt||'—' }}</td><td>{{ archiveDetail.archiveLocationMasked||'—' }}</td></tr></tbody></table></div><p v-else class="section-empty">当前没有后台任务或归档摘要。</p></section>
      <section v-if="remoteMode" class="monitor-panel"><div class="section-heading"><div><h2>运行监控与告警</h2><p>监控告警未配置</p></div></div></section>
      <section class="log-panel"><div class="section-heading"><div><h2>后台操作日志</h2><p>记录 IAM 与平台服务的关键操作，便于审计与追溯。</p></div><span v-if="!remoteMode" class="warning">未处理告警 2</span></div><div v-if="currentLogRows.length" class="table-scroll"><table><thead><tr><th>时间</th><th>操作对象</th><th>操作类型</th><th>详情信息</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in currentLogRows" :key="`${item.time}-${item.target}`"><td>{{ item.time }}</td><td>{{ item.target }}</td><td class="operation-type">{{ item.type }}</td><td>{{ item.detail }}</td><td :class="/PENDING|待处理/i.test(item.status)?'pending':'handled'">{{ item.status }}</td><td><button type="button" :disabled="remoteMode" :title="remoteMode?'日志详情读取合同尚未提供':''" @click="action('查看详情',item.target)">查看详情</button><button type="button" :disabled="remoteMode" :title="remoteMode?'正式处理写入合同尚未提供':''" @click="action('处理记录',item.target)">处理记录</button></td></tr></tbody></table></div><p v-else class="section-empty">当前没有返回后台操作日志。</p></section>
    </template>
    <div v-if="topicDomainDialog" class="dialog-backdrop" @click.self="closeTopicDomainDialog"><section class="topic-domain-dialog" role="dialog" aria-modal="true" aria-labelledby="topic-domain-title"><header><h2 id="topic-domain-title">新增主题域</h2><button type="button" aria-label="关闭" @click="closeTopicDomainDialog">×</button></header><p v-if="remoteMode" class="blocked-copy">正式配置写入合同尚未提供。填写内容不会发送到飞书，需配置 ADM-002 写入合同和权限后才能提交。</p><template v-else><label>主题域名称 *<input v-model="topicDomain.name" placeholder="例如：供应链协同" /></label><label>所属应用 / 类型<input v-model="topicDomain.types" placeholder="例如：数据集 / RPA" /></label><label>图标<select v-model="topicDomain.icon"><option value="apps">应用</option><option value="dataset">数据集</option><option value="report">报表</option><option value="work">协同</option></select></label></template><footer><button type="button" @click="closeTopicDomainDialog">取消</button><button type="button" @click="saveTopicDomain">{{ remoteMode ? '确认限制' : '加入当前会话' }}</button></footer></section></div>
  </article>
</template>

